## Configuration Components (`app/configuration/`, `config/`)

Configuration components handle forms, validation, and data persistence.

### Key Test Areas

1. **Form Validation**
1. **Save/Reset**
1. **Required vs Optional Fields**
1. **Configuration Persistence**
1. **Error Feedback**

### Example: App Configuration Form

```typescript
import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import AppConfigForm from './app-config-form'

vi.mock('@/service/apps', () => ({
  updateAppConfig: vi.fn(),
  getAppConfig: vi.fn(),
}))

import * as appService from '@/service/apps'
const mockedService = vi.mocked(appService)

describe('AppConfigForm', () => {
  const defaultConfig = {
    name: 'My App',
    description: '',
    icon: 'default',
    openingStatement: '',
  }

  beforeEach(() => {
    vi.clearAllMocks()
    mockedService.getAppConfig.mockResolvedValue(defaultConfig)
  })

  describe('Form Validation', () => {
    it('should require app name', async () => {
      const user = userEvent.setup()

      render(<AppConfigForm appId="app-1" />)

      await waitFor(() => {
        expect(screen.getByLabelText(/name/i)).toHaveValue('My App')
      })

      // Clear name field
      await user.clear(screen.getByLabelText(/name/i))
      await user.click(screen.getByRole('button', { name: /save/i }))

      expect(screen.getByText(/name is required/i)).toBeInTheDocument()
      expect(mockedService.updateAppConfig).not.toHaveBeenCalled()
    })

    it('should validate name length', async () => {
      const user = userEvent.setup()

      render(<AppConfigForm appId="app-1" />)

      await waitFor(() => {
        expect(screen.getByLabelText(/name/i)).toBeInTheDocument()
      })

      // Enter very long name
      await user.clear(screen.getByLabelText(/name/i))
      await user.type(screen.getByLabelText(/name/i), 'a'.repeat(101))

      expect(screen.getByText(/name must be less than 100 characters/i)).toBeInTheDocument()
    })

    it('should allow empty optional fields', async () => {
      const user = userEvent.setup()
      mockedService.updateAppConfig.mockResolvedValue({ success: true })

      render(<AppConfigForm appId="app-1" />)

      await waitFor(() => {
        expect(screen.getByLabelText(/name/i)).toHaveValue('My App')
      })

      // Leave description empty (optional)
      await user.click(screen.getByRole('button', { name: /save/i }))

      await waitFor(() => {
        expect(mockedService.updateAppConfig).toHaveBeenCalled()
      })
    })
  })

  describe('Save/Reset Functionality', () => {
    it('should save configuration', async () => {
      const user = userEvent.setup()
      mockedService.updateAppConfig.mockResolvedValue({ success: true })

      render(<AppConfigForm appId="app-1" />)

      await waitFor(() => {
        expect(screen.getByLabelText(/name/i)).toHaveValue('My App')
      })

      await user.clear(screen.getByLabelText(/name/i))
      await user.type(screen.getByLabelText(/name/i), 'Updated App')
      await user.click(screen.getByRole('button', { name: /save/i }))

      await waitFor(() => {
        expect(mockedService.updateAppConfig).toHaveBeenCalledWith(
          'app-1',
          expect.objectContaining({ name: 'Updated App' })
        )
      })

      expect(screen.getByText(/saved successfully/i)).toBeInTheDocument()
    })

    it('should reset to default values', async () => {
      const user = userEvent.setup()

      render(<AppConfigForm appId="app-1" />)

      await waitFor(() => {
        expect(screen.getByLabelText(/name/i)).toHaveValue('My App')
      })

      // Make changes
      await user.clear(screen.getByLabelText(/name/i))
      await user.type(screen.getByLabelText(/name/i), 'Changed Name')

      // Reset
      await user.click(screen.getByRole('button', { name: /reset/i }))

      expect(screen.getByLabelText(/name/i)).toHaveValue('My App')
    })

    it('should show unsaved changes warning', async () => {
      const user = userEvent.setup()

      render(<AppConfigForm appId="app-1" />)

      await waitFor(() => {
        expect(screen.getByLabelText(/name/i)).toHaveValue('My App')
      })

      // Make changes
      await user.type(screen.getByLabelText(/name/i), ' Updated')

      expect(screen.getByText(/unsaved changes/i)).toBeInTheDocument()
    })
  })

  describe('Error Handling', () => {
    it('should show error on save failure', async () => {
      const user = userEvent.setup()
      mockedService.updateAppConfig.mockRejectedValue(new Error('Server error'))

      render(<AppConfigForm appId="app-1" />)

      await waitFor(() => {
        expect(screen.getByLabelText(/name/i)).toHaveValue('My App')
      })

      await user.click(screen.getByRole('button', { name: /save/i }))

      await waitFor(() => {
        expect(screen.getByText(/failed to save/i)).toBeInTheDocument()
      })
    })
  })
})
```

# Mocking Guide for Dify Frontend Tests

## ⚠️ Important: What NOT to Mock

### DO NOT Mock Base Components

**Never mock components from `@/app/components/base/`** such as:

- `Loading`, `Spinner`
- `Button`, `Input`, `Select`
- `Tooltip`, `Modal`, `Dropdown`
- `Icon`, `Badge`, `Tag`

**Why?**

- Base components will have their own dedicated tests
- Mocking them creates false positives (tests pass but real integration fails)
- Using real components tests actual integration behavior

```typescript
// ❌ WRONG: Don't mock base components
vi.mock('@/app/components/base/loading', () => () => <div>Loading</div>)
vi.mock('@/app/components/base/button', () => ({ children }: any) => <button>{children}</button>)

// ✅ CORRECT: Import and use real base components
import Loading from '@/app/components/base/loading'
import Button from '@/app/components/base/button'
// They will render normally in tests
```

### What TO Mock

Only mock these categories:

1. **API services** (`@/service/*`) - Network calls
1. **Complex context providers** - When setup is too difficult
1. **Third-party libraries with side effects** - `next/navigation`, external SDKs
1. **i18n** - Always mock to return keys

## Mock Placement

| Location | Purpose |
|----------|---------|
| `web/vitest.setup.ts` | Global mocks shared by all tests (for example `react-i18next`, `next/image`) |
| `web/__mocks__/` | Reusable mock factories shared across multiple test files |
| Test file | Test-specific mocks, inline with `vi.mock()` |

Modules are not mocked automatically. Use `vi.mock` in test files, or add global mocks in `web/vitest.setup.ts`.

## Essential Mocks

### 1. i18n (Auto-loaded via Global Mock)

A global mock is defined in `web/vitest.setup.ts` and is auto-loaded by Vitest setup.

The global mock provides:

- `useTranslation` - returns translation keys with namespace prefix
- `Trans` component - renders i18nKey and components
- `useMixedTranslation` (from `@/app/components/plugins/marketplace/hooks`)
- `useGetLanguage` (from `@/context/i18n`) - returns `'en-US'`

**Default behavior**: Most tests should use the global mock (no local override needed).

**For custom translations**: Use the helper function from `@/test/i18n-mock`:

```typescript
import { createReactI18nextMock } from '@/test/i18n-mock'

vi.mock('react-i18next', () => createReactI18nextMock({
  'my.custom.key': 'Custom translation',
  'button.save': 'Save',
}))
```

**Avoid**: Manually defining `useTranslation` mocks that just return the key - the global mock already does this.

### 2. Next.js Router

```typescript
const mockPush = vi.fn()
const mockReplace = vi.fn()

vi.mock('next/navigation', () => ({
  useRouter: () => ({
    push: mockPush,
    replace: mockReplace,
    back: vi.fn(),
    prefetch: vi.fn(),
  }),
  usePathname: () => '/current-path',
  useSearchParams: () => new URLSearchParams('?key=value'),
}))

describe('Component', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('should navigate on click', () => {
    render(<Component />)
    fireEvent.click(screen.getByRole('button'))
    expect(mockPush).toHaveBeenCalledWith('/expected-path')
  })
})
```

### 3. Portal Components (with Shared State)

```typescript
// ⚠️ Important: Use shared state for components that depend on each other
let mockPortalOpenState = false

vi.mock('@/app/components/base/portal-to-follow-elem', () => ({
  PortalToFollowElem: ({ children, open, ...props }: any) => {
    mockPortalOpenState = open || false  // Update shared state
    return <div data-testid="portal" data-open={open}>{children}</div>
  },
  PortalToFollowElemContent: ({ children }: any) => {
    // ✅ Matches actual: returns null when portal is closed
    if (!mockPortalOpenState) return null
    return <div data-testid="portal-content">{children}</div>
  },
  PortalToFollowElemTrigger: ({ children }: any) => (
    <div data-testid="portal-trigger">{children}</div>
  ),
}))

describe('Component', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    mockPortalOpenState = false  // ✅ Reset shared state
  })
})
```

### 4. API Service Mocks

```typescript
import * as api from '@/service/api'

vi.mock('@/service/api')

const mockedApi = vi.mocked(api)

describe('Component', () => {
  beforeEach(() => {
    vi.clearAllMocks()

    // Setup default mock implementation
    mockedApi.fetchData.mockResolvedValue({ data: [] })
  })

  it('should show data on success', async () => {
    mockedApi.fetchData.mockResolvedValue({ data: [{ id: 1 }] })

    render(<Component />)

    await waitFor(() => {
      expect(screen.getByText('1')).toBeInTheDocument()
    })
  })

  it('should show error on failure', async () => {
    mockedApi.fetchData.mockRejectedValue(new Error('Network error'))

    render(<Component />)

    await waitFor(() => {
      expect(screen.getByText(/error/i)).toBeInTheDocument()
    })
  })
})
```

### 5. HTTP Mocking with Nock

```typescript
import nock from 'nock'

const GITHUB_HOST = 'https://api.github.com'
const GITHUB_PATH = '/repos/owner/repo'

const mockGithubApi = (status: number, body: Record<string, unknown>, delayMs = 0) => {
  return nock(GITHUB_HOST)
    .get(GITHUB_PATH)
    .delay(delayMs)
    .reply(status, body)
}

describe('GithubComponent', () => {
  afterEach(() => {
    nock.cleanAll()
  })

  it('should display repo info', async () => {
    mockGithubApi(200, { name: 'dify', stars: 1000 })

    render(<GithubComponent />)

    await waitFor(() => {
      expect(screen.getByText('dify')).toBeInTheDocument()
    })
  })

  it('should handle API error', async () => {
    mockGithubApi(500, { message: 'Server error' })

    render(<GithubComponent />)

    await waitFor(() => {
      expect(screen.getByText(/error/i)).toBeInTheDocument()
    })
  })
})
```

### 6. Context Providers

```typescript
import { ProviderContext } from '@/context/provider-context'
import { createMockProviderContextValue, createMockPlan } from '@/__mocks__/provider-context'

describe('Component with Context', () => {
  it('should render for free plan', () => {
    const mockContext = createMockPlan('sandbox')

    render(
      <ProviderContext.Provider value={mockContext}>
        <Component />
      </ProviderContext.Provider>
    )

    expect(screen.getByText('Upgrade')).toBeInTheDocument()
  })

  it('should render for pro plan', () => {
    const mockContext = createMockPlan('professional')

    render(
      <ProviderContext.Provider value={mockContext}>
        <Component />
      </ProviderContext.Provider>
    )

    expect(screen.queryByText('Upgrade')).not.toBeInTheDocument()
  })
})
```

### 7. React Query

```typescript
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'

const createTestQueryClient = () => new QueryClient({
  defaultOptions: {
    queries: { retry: false },
    mutations: { retry: false },
  },
})

const renderWithQueryClient = (ui: React.ReactElement) => {
  const queryClient = createTestQueryClient()
  return render(
    <QueryClientProvider client={queryClient}>
      {ui}
    </QueryClientProvider>
  )
}
```

## Mock Best Practices

### ✅ DO

1. **Use real base components** - Import from `@/app/components/base/` directly
1. **Use real project components** - Prefer importing over mocking
1. **Reset mocks in `beforeEach`**, not `afterEach`
1. **Match actual component behavior** in mocks (when mocking is necessary)
1. **Use factory functions** for complex mock data
1. **Import actual types** for type safety
1. **Reset shared mock state** in `beforeEach`

### ❌ DON'T

1. **Don't mock base components** (`Loading`, `Button`, `Tooltip`, etc.)
1. Don't mock components you can import directly
1. Don't create overly simplified mocks that miss conditional logic
1. Don't forget to clean up nock after each test
1. Don't use `any` types in mocks without necessity

### Mock Decision Tree

```
Need to use a component in test?
│
├─ Is it from @/app/components/base/*?
│  └─ YES → Import real component, DO NOT mock
│
├─ Is it a project component?
│  └─ YES → Prefer importing real component
│           Only mock if setup is extremely complex
│
├─ Is it an API service (@/service/*)?
│  └─ YES → Mock it
│
├─ Is it a third-party lib with side effects?
│  └─ YES → Mock it (next/navigation, external SDKs)
│
└─ Is it i18n?
   └─ YES → Uses shared mock (auto-loaded). Override only for custom translations
```

## Factory Function Pattern

```typescript
// __mocks__/data-factories.ts
import type { User, Project } from '@/types'

export const createMockUser = (overrides: Partial<User> = {}): User => ({
  id: 'user-1',
  name: 'Test User',
  email: 'test@example.com',
  role: 'member',
  createdAt: new Date().toISOString(),
  ...overrides,
})

export const createMockProject = (overrides: Partial<Project> = {}): Project => ({
  id: 'project-1',
  name: 'Test Project',
  description: 'A test project',
  owner: createMockUser(),
  members: [],
  createdAt: new Date().toISOString(),
  ...overrides,
})

// Usage in tests
it('should display project owner', () => {
  const project = createMockProject({
    owner: createMockUser({ name: 'John Doe' }),
  })

  render(<ProjectCard project={project} />)
  expect(screen.getByText('John Doe')).toBeInTheDocument()
})
```

# Common Vue Testing Patterns

## Finding Elements

Prefer `findComponent` for Vue components and `find` (with role/class selectors) for DOM elements.

```typescript
// Find by Component
const child = wrapper.findComponent(ChildComponent)
expect(child.exists()).toBe(true)

// Find by class (discouraged if role available)
const btn = wrapper.find('.submit-btn')

// Find by role (Testing Library style)
// Requires @testing-library/vue if you prefer that style, 
// but VTU `find` is dominant in Vue ecosystem.
```

## Testing Events (Emits)

Events are the primary contract of a Vue component.

```typescript
// Triggering
await wrapper.find('input').setValue('new text')
await wrapper.find('form').trigger('submit.prevent')

// Asserting
expect(wrapper.emitted('update:modelValue')).toBeTruthy()
expect(wrapper.emitted('update:modelValue')![0]).toEqual(['new text'])
```

## Testing Slots

```typescript
const wrapper = mount(Component, {
  slots: {
    default: 'Default Content',
    header: '<div class="header">Header Content</div>'
  }
})

expect(wrapper.html()).toContain('Header Content')
```

## Snapshot Testing

Use sparingly for regression testing of complex static UI.

```typescript
it('matches snapshot', () => {
  const wrapper = mount(Component)
  expect(wrapper.html()).toMatchSnapshot()
})
```

# Vue 2 Testing Patterns (Vue Test Utils v1)

## Setup

```javascript
import { shallowMount, mount, createLocalVue } from '@vue/test-utils'
import Vuex from 'vuex'
import Component from '@/components/Component.vue'

const localVue = createLocalVue()
localVue.use(Vuex)

describe('Component.vue', () => {
  let actions
  let store

  beforeEach(() => {
    actions = {
      actionClick: jest.fn()
    }
    store = new Vuex.Store({
      actions
    })
  })

  it('renders props.msg when passed', () => {
    const msg = 'new message'
    const wrapper = shallowMount(Component, {
      propsData: { msg }
    })
    expect(wrapper.text()).toMatch(msg)
  })

  it('dispatches action on click', async () => {
    const wrapper = shallowMount(Component, { store, localVue })
    const button = wrapper.find('button')
    await button.trigger('click')
    expect(actions.actionClick).toHaveBeenCalled()
  })
})
```

## Key API Differences (vs VTU v2)

- Use `createLocalVue()` to avoid polluting global Vue.
- `propsData` instead of `props`.
- `mocks` option to mock `$route`, `$router`.
- `stubs` to shallow render children.

# Vue 3 Testing Patterns (Vue Test Utils v2)

## Setup

```typescript
import { mount } from '@vue/test-utils'
import { describe, it, expect, vi } from 'vitest'
import Component from '@/components/Component.vue'
import { createStore } from 'vuex' // or Pinia

describe('Component.vue', () => {
  it('renders props properly', () => {
    const wrapper = mount(Component, {
      props: {
        title: 'Hello'
      }
    })
    expect(wrapper.text()).toContain('Hello')
  })

  it('emits event on button click', async () => {
    const wrapper = mount(Component)
    await wrapper.find('button').trigger('click')
    
    expect(wrapper.emitted()).toHaveProperty('submit')
    expect(wrapper.emitted('submit')![0]).toEqual([123])
  })
})
```

## Testing Pinia

```typescript
import { setActivePinia, createPinia } from 'pinia'
import { useCounterStore } from '@/stores/counter'

describe('Counter Store', () => {
  beforeEach(() => {
    setActivePinia(createPinia())
  })

  it('increments', () => {
    const counter = useCounterStore()
    expect(counter.count).toBe(0)
    counter.increment()
    expect(counter.count).toBe(1)
  })
})
```

## Key API Differences (vs VTU v1)

- No `createLocalVue`. Plugins are installed via `global.plugins`.
- `props` instead of `propsData`.
- `wrapper.emitted()` returns array of arrays.
- `slots` configuration is slightly different.

# Accessibility Workflow

Use this reference when the task is about WCAG compliance, ARIA usage, keyboard navigation, or focus management.

## WCAG 2.1 AA Checklist

### Perceivable

- [ ] Images have meaningful `alt` text
- [ ] Video content has captions where needed
- [ ] Text contrast meets 4.5:1, large text meets 3:1
- [ ] Color is not the only signal

### Operable

- [ ] Every interaction works by keyboard
- [ ] Focus styles are visible
- [ ] No keyboard trap exists
- [ ] Skip links exist for repeated navigation

### Understandable

- [ ] `lang` is declared
- [ ] Forms have explicit labels and clear errors
- [ ] Naming and navigation are consistent

### Robust

- [ ] Semantic HTML is preferred over ARIA recreation
- [ ] ARIA attributes match actual behavior
- [ ] Screen-reader announcements are intentional

## ARIA Patterns

```vue
<button
  :aria-pressed="isActive"
  :aria-label="t('toggleMenu')"
>
  <Icon name="menu" aria-hidden="true" />
</button>

<div
  role="dialog"
  aria-modal="true"
  :aria-labelledby="titleId"
  :aria-describedby="descId"
>
  <h2 :id="titleId">{{ title }}</h2>
  <p :id="descId">{{ description }}</p>
</div>
```

## Keyboard And Focus

```typescript
function handleKeydown(event: KeyboardEvent) {
  switch (event.key) {
    case 'ArrowDown':
      focusNextItem();
      event.preventDefault();
      break;
    case 'ArrowUp':
      focusPrevItem();
      event.preventDefault();
      break;
    case 'Enter':
    case ' ':
      selectItem();
      event.preventDefault();
      break;
    case 'Escape':
      closeMenu();
      break;
  }
}
```

```typescript
async function openDialog() {
  isOpen.value = true;
  await nextTick();
  dialogRef.value?.focus();
}

function closeDialog() {
  isOpen.value = false;
  triggerButtonRef.value?.focus();
}
```

